#!/usr/bin/env python3
# CUI // SP-CTI — IaC Validation Engine
"""Validates Infrastructure-as-Code generated by the Pipeline Design Canvas.

5-layer validation pyramid:
  Layer 1 — Syntax: Is each file parseable? (terraform fmt, YAML parse, HCL parse)
  Layer 2 — Schema: Are resource types and fields valid? (kubeconform, cfn-lint)
  Layer 3 — Policy: Does it meet security policies? (Checkov, tfsec, OPA)
  Layer 4 — Plan:   What would change? (terraform plan --dry-run)
  Layer 5 — Deploy: Does it work? (ephemeral env with LocalStack/kind)

Layers 1-3 run offline (air-gap safe). Layers 4-5 need credentials or local emulation.

Usage:
    python tools/pipeline/iac_validator.py --bundle /path/to/deploy-bundle --json
    python tools/pipeline/iac_validator.py --bundle /path/to/deploy-bundle --layer 1-3
    python tools/pipeline/iac_validator.py --content '{"files": [...]}' --json
"""

import argparse
import json
import logging
import shutil
import subprocess
import tempfile
from datetime import datetime, timezone
from pathlib import Path

logger = logging.getLogger("icdev.iac_validator")

BASE_DIR = Path(__file__).resolve().parent.parent.parent


# ── Result Types ──────────────────────────────────────────────────────────────


class ValidationResult:
    def __init__(self, layer, check_name, status, message, file_path=None, details=None):
        self.layer = layer
        self.check_name = check_name
        self.status = status  # pass, fail, warn, skip
        self.message = message
        self.file_path = file_path
        self.details = details or []

    def to_dict(self):
        return {
            "layer": self.layer,
            "check": self.check_name,
            "status": self.status,
            "message": self.message,
            "file": self.file_path,
            "details": self.details,
        }


def validate_bundle(files, max_layer=3):
    """Validate a deployment bundle through the specified layers.

    Args:
        files: list of {"path": str, "content": str} dicts (from deploy_generator)
        max_layer: highest validation layer to run (1-5, default 3)

    Returns:
        dict with results, summary, gate status
    """
    results = []

    # Layer 1: Syntax validation
    if max_layer >= 1:
        results.extend(_layer1_syntax(files))

    # Layer 2: Schema validation
    if max_layer >= 2:
        results.extend(_layer2_schema(files))

    # Layer 3: Policy validation
    if max_layer >= 3:
        results.extend(_layer3_policy(files))

    # Layer 4: Plan (requires credentials)
    if max_layer >= 4:
        results.extend(_layer4_plan(files))

    # Layer 5: Deploy test (requires local emulation)
    if max_layer >= 5:
        results.extend(_layer5_deploy_test(files))

    # Compute summary
    passed = sum(1 for r in results if r.status == "pass")
    failed = sum(1 for r in results if r.status == "fail")
    warned = sum(1 for r in results if r.status == "warn")
    skipped = sum(1 for r in results if r.status == "skip")

    gate = "pass" if failed == 0 else "fail"

    return {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "layers_run": max_layer,
        "results": [r.to_dict() for r in results],
        "summary": {
            "total": len(results),
            "passed": passed,
            "failed": failed,
            "warned": warned,
            "skipped": skipped,
        },
        "gate": gate,
    }


# ── Layer 1: Syntax ──────────────────────────────────────────────────────────


def _layer1_syntax(files):
    """Validate file syntax — parseable HCL, valid YAML, valid JSON."""
    results = []

    for f in files:
        path = f["path"]
        content = f["content"]

        if path.endswith(".tf"):
            results.append(_check_hcl_syntax(path, content))
        elif path.endswith((".yaml", ".yml")):
            results.append(_check_yaml_syntax(path, content))
        elif path.endswith(".json"):
            results.append(_check_json_syntax(path, content))
        elif path.endswith(".sh"):
            results.append(_check_shell_syntax(path, content))

    return results


def _check_hcl_syntax(path, content):
    """Validate Terraform HCL syntax."""
    # Basic structural checks without terraform binary
    issues = []

    # Check balanced braces
    open_braces = content.count("{")
    close_braces = content.count("}")
    if open_braces != close_braces:
        issues.append(f"Unbalanced braces: {open_braces} open, {close_braces} close")

    # Check for common HCL errors
    lines = content.split("\n")
    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        # Check for = without quotes on string values
        if "= " in stripped and not stripped.startswith("#") and not stripped.startswith("//"):
            if stripped.endswith("{") or stripped.endswith("["):
                continue
            # Check if resource/variable/output blocks are properly formed
            if stripped.startswith(("resource ", "variable ", "output ", "data ", "module ", "provider ", "locals ")):
                if "{" not in stripped:
                    issues.append(f"Line {i}: Block declaration missing opening brace")

    # Check for required blocks — warn (not fail) if main.tf has resources but no provider
    # Provider may be in a parent directory or separate provider.tf
    has_provider = "provider " in content or 'provider "' in content
    has_resources = "resource " in content
    basename = Path(path).name
    if has_resources and not has_provider and basename == "main.tf":
        issues.append("main.tf has resources but no provider block (may inherit from parent module)")

    if issues:
        # Classify: structural errors are fail, informational are warn
        has_structural = any("Unbalanced" in i or "missing opening brace" in i for i in issues)
        severity = "fail" if has_structural else "warn"
        return ValidationResult(1, "hcl_syntax", severity, f"{len(issues)} syntax note(s)", path, issues)
    return ValidationResult(1, "hcl_syntax", "pass", "HCL syntax valid", path)


def _check_yaml_syntax(path, content):
    """Validate YAML syntax."""
    try:
        import yaml

        docs = list(yaml.safe_load_all(content))
        if not docs or all(d is None for d in docs):
            return ValidationResult(1, "yaml_syntax", "warn", "YAML file is empty or contains only comments", path)
        return ValidationResult(1, "yaml_syntax", "pass", f"Valid YAML ({len(docs)} document(s))", path)
    except ImportError:
        # Fallback: basic YAML checks
        issues = []
        lines = content.split("\n")
        for i, line in enumerate(lines, 1):
            if "\t" in line and not line.strip().startswith("#"):
                issues.append(f"Line {i}: Tab character (YAML requires spaces)")
        if issues:
            return ValidationResult(1, "yaml_syntax", "fail", f"{len(issues)} issue(s)", path, issues)
        return ValidationResult(1, "yaml_syntax", "pass", "Basic YAML checks passed", path)
    except Exception as exc:
        return ValidationResult(1, "yaml_syntax", "fail", f"YAML parse error: {exc}", path)


def _check_json_syntax(path, content):
    """Validate JSON syntax."""
    try:
        json.loads(content)
        return ValidationResult(1, "json_syntax", "pass", "Valid JSON", path)
    except json.JSONDecodeError as exc:
        return ValidationResult(1, "json_syntax", "fail", f"JSON parse error: {exc}", path)


def _check_shell_syntax(path, content):
    """Validate shell script syntax."""
    issues = []
    if not content.strip().startswith(("#!/bin/bash", "#!/bin/sh", "#")):
        issues.append("Missing shebang (#!/bin/bash)")
    if "set -e" not in content and "set -euo" not in content:
        issues.append("Missing 'set -e' (exit on error) — risky for deployment scripts")
    if issues:
        return ValidationResult(1, "shell_syntax", "warn", f"{len(issues)} suggestion(s)", path, issues)
    return ValidationResult(1, "shell_syntax", "pass", "Shell script looks valid", path)


# ── Layer 2: Schema ──────────────────────────────────────────────────────────


def _layer2_schema(files):
    """Validate resource schemas — correct types, required fields."""
    results = []

    for f in files:
        path = f["path"]
        content = f["content"]

        if path.endswith(".tf"):
            results.append(_check_tf_resources(path, content))
        elif path.endswith((".yaml", ".yml")) and "values/" in path:
            results.append(_check_helm_values(path, content))
        elif path.endswith(".yaml") and "ci-config" in path:
            results.append(_check_ci_config(path, content))

    return results


def _check_tf_resources(path, content):
    """Validate Terraform resource types are real."""
    known_prefixes = {
        "aws_",
        "azurerm_",
        "google_",
        "oci_",
        "ibm_",
        "helm_",
        "kubernetes_",
        "null_",
        "random_",
        "local_",
        "tls_",
        "docker_",
    }
    issues = []
    import re

    for match in re.finditer(r'resource\s+"(\w+)"\s+"(\w+)"', content):
        resource_type = match.group(1)
        if not any(resource_type.startswith(p) for p in known_prefixes):
            issues.append(f"Unknown resource type: {resource_type}")

    # Check for required fields in common resources
    if "aws_eks_cluster" in content and "subnet_ids" not in content and "vpc_id" not in content:
        issues.append("aws_eks_cluster missing subnet_ids or vpc_id")
    if "azurerm_kubernetes_cluster" in content and "default_node_pool" not in content:
        issues.append("azurerm_kubernetes_cluster missing default_node_pool")

    if issues:
        return ValidationResult(2, "tf_resources", "warn", f"{len(issues)} resource concern(s)", path, issues)
    return ValidationResult(2, "tf_resources", "pass", "Resource types valid", path)


def _check_helm_values(path, content):
    """Validate Helm values have expected structure."""
    try:
        import yaml

        values = yaml.safe_load(content)
        if not isinstance(values, dict):
            return ValidationResult(2, "helm_values", "warn", "Values file is not a dict", path)

        chart_name = Path(path).stem  # e.g., "harbor" from "values/harbor.yaml"
        issues = []

        # Check common required fields per chart
        required_fields = {
            "harbor": ["expose", "persistence"],
            "vault": ["server"],
            "kube-prometheus-stack": ["prometheus", "grafana"],
            "argocd": ["server"],
        }
        for field in required_fields.get(chart_name, []):
            if field not in (values or {}):
                issues.append(f"Missing expected field: {field}")

        if issues:
            return ValidationResult(2, "helm_values", "warn", f"{len(issues)} suggestion(s)", path, issues)
        return ValidationResult(2, "helm_values", "pass", f"Helm values valid for {chart_name}", path)
    except Exception as exc:
        return ValidationResult(2, "helm_values", "fail", f"Parse error: {exc}", path)


def _check_ci_config(path, content):
    """Validate CI/CD configuration."""
    issues = []
    if ".gitlab-ci" in path:
        if "stages:" not in content:
            issues.append("GitLab CI missing 'stages:' block")
        if "script:" not in content:
            issues.append("GitLab CI has no 'script:' commands")
    elif "azure-pipelines" in path:
        if "trigger:" not in content and "pr:" not in content:
            issues.append("Azure Pipelines missing trigger")
    if issues:
        return ValidationResult(2, "ci_config", "warn", f"{len(issues)} issue(s)", path, issues)
    return ValidationResult(2, "ci_config", "pass", "CI config structure valid", path)


# ── Layer 3: Policy ──────────────────────────────────────────────────────────


def _layer3_policy(files):
    """Validate security policies — encryption, access control, compliance."""
    results = []

    tf_files = [f for f in files if f["path"].endswith(".tf")]
    helm_files = [f for f in files if "values/" in f["path"]]
    all_content = "\n".join(f["content"] for f in files)

    # Policy: Encryption at rest
    results.append(_check_encryption_policy(tf_files))

    # Policy: No hardcoded secrets
    results.append(_check_no_secrets(files))

    # Policy: Tags/labels required
    results.append(_check_tagging_policy(tf_files))

    # Policy: Network security
    results.append(_check_network_policy(tf_files))

    # Policy: Helm security
    for hf in helm_files:
        results.append(_check_helm_security(hf))

    # Policy: FIPS compliance (GovCloud)
    results.append(_check_fips_policy(all_content))

    return results


def _check_encryption_policy(tf_files):
    """Check that storage and databases use encryption."""
    all_tf = "\n".join(f["content"] for f in tf_files)
    issues = []

    if "aws_s3_bucket" in all_tf and "server_side_encryption" not in all_tf:
        issues.append("S3 bucket without server_side_encryption_configuration")
    if "aws_rds" in all_tf and "storage_encrypted" not in all_tf:
        issues.append("RDS without storage_encrypted = true")
    if "azurerm_storage_account" in all_tf and "min_tls_version" not in all_tf:
        issues.append("Azure Storage without min_tls_version")

    if issues:
        return ValidationResult(3, "encryption_policy", "fail", f"{len(issues)} encryption gap(s)", None, issues)
    return ValidationResult(3, "encryption_policy", "pass", "Encryption policies satisfied")


def _check_no_secrets(files):
    """Check for hardcoded secrets in generated files."""
    import re

    secret_patterns = [
        (r'(?i)(password|secret|api_key|access_key)\s*=\s*"[^"]{8,}"', "Possible hardcoded secret"),
        (r"AKIA[0-9A-Z]{16}", "AWS access key"),
        (r"(?i)BEGIN\s+(RSA|DSA|EC|OPENSSH)\s+PRIVATE\s+KEY", "Private key"),
    ]
    issues = []
    for f in files:
        for pattern, desc in secret_patterns:
            if re.search(pattern, f["content"]):
                issues.append(f"{f['path']}: {desc}")

    if issues:
        return ValidationResult(3, "no_secrets", "fail", f"{len(issues)} potential secret(s)", None, issues)
    return ValidationResult(3, "no_secrets", "pass", "No hardcoded secrets detected")


def _check_tagging_policy(tf_files):
    """Check that resources have required tags."""
    all_tf = "\n".join(f["content"] for f in tf_files)
    has_tags = "tags" in all_tf or "labels" in all_tf
    if not has_tags and "resource " in all_tf:
        return ValidationResult(3, "tagging_policy", "warn", "Resources missing tags/labels block")
    return ValidationResult(3, "tagging_policy", "pass", "Resources have tags/labels")


def _check_network_policy(tf_files):
    """Check network security basics."""
    all_tf = "\n".join(f["content"] for f in tf_files)
    issues = []

    if "0.0.0.0/0" in all_tf:
        # Check if it's in a public subnet (OK) or security group (bad)
        if "ingress" in all_tf and "0.0.0.0/0" in all_tf:
            issues.append("Security group ingress open to 0.0.0.0/0 — restrict to specific CIDRs")

    if "cluster_endpoint_public_access" in all_tf and "true" in all_tf:
        issues.append("EKS cluster endpoint is public — consider private endpoint for production")

    if issues:
        return ValidationResult(3, "network_policy", "warn", f"{len(issues)} network concern(s)", None, issues)
    return ValidationResult(3, "network_policy", "pass", "Network policies reasonable")


def _check_helm_security(helm_file):
    """Check Helm values for security best practices."""
    content = helm_file["content"]
    path = helm_file["path"]
    issues = []

    if "adminPassword: changeme" in content or "password: changeme" in content:
        issues.append("Default password 'changeme' — MUST be changed before deploy")
    if "runAsRoot: true" in content or "privileged: true" in content:
        issues.append("Container running as root or privileged — security risk")

    if issues:
        return ValidationResult(3, "helm_security", "warn", f"{len(issues)} security concern(s)", path, issues)
    return ValidationResult(3, "helm_security", "pass", "Helm values security OK", path)


def _check_fips_policy(all_content):
    """Check FIPS 140 compliance indicators for GovCloud."""
    fips_indicators = ["fips" in all_content.lower(), "us-gov" in all_content, "govcloud" in all_content.lower()]
    is_govcloud = any(fips_indicators)

    if is_govcloud:
        issues = []
        if "fips_endpoints" not in all_content.lower() and "fips" not in all_content.lower():
            issues.append("GovCloud deployment without explicit FIPS endpoint configuration")
        if issues:
            return ValidationResult(3, "fips_policy", "warn", "GovCloud FIPS concern", None, issues)
        return ValidationResult(3, "fips_policy", "pass", "FIPS configuration detected for GovCloud")
    return ValidationResult(3, "fips_policy", "pass", "Non-GovCloud — FIPS not required")


# ── Layer 4: Plan (requires credentials) ─────────────────────────────────────


def _layer4_plan(files):
    """Run terraform plan if terraform binary available and credentials configured."""
    if not shutil.which("terraform"):
        return [ValidationResult(4, "terraform_plan", "skip", "terraform binary not found — install to enable Layer 4")]

    # Write files to temp dir and run terraform init + plan
    results = []
    tf_files = [f for f in files if f["path"].endswith(".tf")]
    if not tf_files:
        return [ValidationResult(4, "terraform_plan", "skip", "No Terraform files in bundle")]

    with tempfile.TemporaryDirectory() as tmpdir:
        # Group TF files by directory
        dirs = {}
        for f in tf_files:
            d = str(Path(f["path"]).parent)
            dirs.setdefault(d, []).append(f)

        for tf_dir, dir_files in dirs.items():
            target = Path(tmpdir) / tf_dir
            target.mkdir(parents=True, exist_ok=True)
            for f in dir_files:
                (target / Path(f["path"]).name).write_text(f["content"], encoding="utf-8")

            # terraform validate (doesn't need credentials)
            try:
                proc = subprocess.run(
                    ["terraform", "validate"],
                    capture_output=True,
                    text=True,
                    timeout=30,
                    cwd=str(target),
                )
                if proc.returncode == 0:
                    results.append(
                        ValidationResult(
                            4, "terraform_validate", "pass", f"terraform validate passed for {tf_dir}", tf_dir
                        )
                    )
                else:
                    results.append(
                        ValidationResult(
                            4, "terraform_validate", "fail", f"terraform validate failed: {proc.stderr[:200]}", tf_dir
                        )
                    )
            except FileNotFoundError:
                results.append(
                    ValidationResult(4, "terraform_validate", "skip", "terraform init required first", tf_dir)
                )
            except subprocess.TimeoutExpired:
                results.append(
                    ValidationResult(4, "terraform_validate", "skip", "terraform validate timed out", tf_dir)
                )
            except Exception as exc:
                results.append(ValidationResult(4, "terraform_validate", "skip", f"Error: {exc}", tf_dir))

    return results


# ── Layer 5: Deploy Test (requires local emulation) ──────────────────────────


def _layer5_deploy_test(files):
    """Test deployment in ephemeral environment (LocalStack, kind, etc.)."""
    results = []

    # Check for LocalStack
    if shutil.which("localstack"):
        results.append(ValidationResult(5, "localstack_available", "pass", "LocalStack available for AWS emulation"))
    else:
        results.append(
            ValidationResult(
                5, "localstack_available", "skip", "LocalStack not installed — install for Layer 5 AWS testing"
            )
        )

    # Check for kind (Kubernetes in Docker)
    if shutil.which("kind"):
        results.append(ValidationResult(5, "kind_available", "pass", "kind available for K8s testing"))
    else:
        results.append(
            ValidationResult(5, "kind_available", "skip", "kind not installed — install for Layer 5 K8s testing")
        )

    # Check for helm
    if shutil.which("helm"):
        helm_files = [f for f in files if "values/" in f["path"]]
        for hf in helm_files:
            chart_name = Path(hf["path"]).stem
            results.append(
                ValidationResult(
                    5,
                    f"helm_template_{chart_name}",
                    "skip",
                    f"Helm template test available for {chart_name} — run with 'helm template'",
                )
            )
    else:
        results.append(ValidationResult(5, "helm_available", "skip", "helm not installed"))

    return results


# ── API Integration ──────────────────────────────────────────────────────────


def validate_deploy_bundle_from_generator(graph, name, target_csp="auto", max_layer=3):
    """Generate a deploy bundle and validate it in one call.

    Used by the Pipeline Canvas "Validate" button.
    """
    from tools.pipeline.deploy_generator import generate_deploy_bundle

    bundle = generate_deploy_bundle(graph, name, target_csp)
    validation = validate_bundle(bundle["files"], max_layer)
    return {
        "bundle_summary": bundle["summary"],
        "validation": validation,
        "file_count": len(bundle["files"]),
    }


# ── CLI ──────────────────────────────────────────────────────────────────────


def main():
    parser = argparse.ArgumentParser(description="IaC Validation Engine")
    parser.add_argument("--bundle", help="Path to deploy bundle directory")
    parser.add_argument("--content", help="JSON string with files array")
    parser.add_argument("--layer", default="1-3", help="Validation layers to run (e.g., 1-3, 1-5)")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()

    # Parse layer range
    if "-" in args.layer:
        max_layer = int(args.layer.split("-")[1])
    else:
        max_layer = int(args.layer)

    # Load files
    files = []
    if args.content:
        data = json.loads(args.content)
        files = data.get("files", data) if isinstance(data, dict) else data
    elif args.bundle:
        bundle_path = Path(args.bundle)
        for fp in bundle_path.rglob("*"):
            if fp.is_file():
                rel = str(fp.relative_to(bundle_path))
                files.append({"path": rel, "content": fp.read_text(encoding="utf-8", errors="replace")})
    else:
        # Generate a test bundle
        from tools.pipeline.deploy_generator import generate_deploy_bundle

        test_graph = {
            "nodes": [
                {"type": "scm-gitlab", "label": "GitLab"},
                {"type": "registry-harbor", "label": "Harbor"},
                {"type": "aws-eks", "label": "EKS"},
                {"type": "mon-prometheus", "label": "Prometheus"},
            ],
            "edges": [],
        }
        bundle = generate_deploy_bundle(test_graph, "Validation Test")
        files = bundle["files"]

    result = validate_bundle(files, max_layer)

    if args.json:
        print(json.dumps(result, indent=2))
    else:
        print(f"IaC Validation (Layers 1-{max_layer})")
        print(f"{'=' * 50}")
        for r in result["results"]:
            icon = {"pass": "PASS", "fail": "FAIL", "warn": "WARN", "skip": "SKIP"}[r["status"]]
            print(f"  [{icon}] L{r['layer']} {r['check']}: {r['message']}")
            for d in r.get("details", []):
                print(f"         {d}")
        print(
            f"\nSummary: {result['summary']['passed']} pass, {result['summary']['failed']} fail, "
            f"{result['summary']['warned']} warn, {result['summary']['skipped']} skip"
        )
        print(f"Gate: {result['gate'].upper()}")


if __name__ == "__main__":
    main()
